import mongoose from 'mongoose';

/**
 * A project generated by the AI Project Builder.
 *
 * Files are stored as text in MongoDB (never binaries). Ownership is enforced
 * on every route, and `requestId` makes the generation endpoint idempotent so a
 * double-click cannot spend two credits or create two projects.
 */
export const PROJECT_STACKS = ['html-css-js', 'react', 'react-express', 'mern', 'python'];
export const PROJECT_COMPLEXITIES = ['starter', 'standard', 'advanced'];

const fileSchema = new mongoose.Schema(
  {
    path: { type: String, required: true, trim: true, maxlength: 300 },
    language: { type: String, trim: true, maxlength: 40, default: 'text' },
    content: { type: String, default: '', maxlength: 60000 },
    updatedAt: { type: Date, default: Date.now },
  },
  { _id: false }
);

const aiProjectSchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    /** Client request id for idempotent generation; omitted when not supplied. */
    requestId: { type: String, trim: true, maxlength: 80 },
    title: { type: String, trim: true, maxlength: 160, default: 'Untitled AI project' },
    description: { type: String, trim: true, maxlength: 1200, default: '' },
    idea: { type: String, trim: true, maxlength: 2000, required: true },
    stack: { type: String, enum: PROJECT_STACKS, required: true },
    stackLabel: { type: String, trim: true, maxlength: 120, default: '' },
    complexity: { type: String, enum: PROJECT_COMPLEXITIES, default: 'standard' },
    designPreferences: { type: String, trim: true, maxlength: 800, default: '' },
    status: { type: String, enum: ['generating', 'ready', 'failed'], default: 'generating', index: true },
    entryFile: { type: String, trim: true, maxlength: 300, default: 'index.html' },
    files: { type: [fileSchema], default: [] },
    readme: { type: String, default: '', maxlength: 40000 },
    techStack: { type: [String], default: [] },
    dependencies: { type: [String], default: [] },
    setupSteps: { type: [String], default: [] },
    /** REST endpoints the generated frontend/backend share (informational). */
    apiEndpoints: {
      type: [
        new mongoose.Schema(
          { method: String, path: String, description: String },
          { _id: false }
        ),
      ],
      default: [],
    },
    /** Inline preview document, only for stacks that render without a build. */
    previewHtml: { type: String, default: '', maxlength: 500000 },
    previewSupported: { type: Boolean, default: false },
    provider: { type: String, trim: true, maxlength: 40, default: '' },
    model: { type: String, trim: true, maxlength: 120, default: '' },
    creditsUsed: { type: Number, default: 0 },
    generatedAt: { type: Date, default: null },
    errorCode: { type: String, trim: true, maxlength: 60, default: '' },
    errorMessage: { type: String, trim: true, maxlength: 600, default: '' },
  },
  { timestamps: true, versionKey: false }
);

aiProjectSchema.index({ userId: 1, createdAt: -1 });
aiProjectSchema.index(
  { userId: 1, requestId: 1 },
  { unique: true, partialFilterExpression: { requestId: { $exists: true } } }
);

/** Summary shown in the "My AI projects" list. */
aiProjectSchema.methods.toSummaryJSON = function toSummaryJSON() {
  return {
    id: this._id.toString(),
    title: this.title,
    description: this.description,
    idea: this.idea,
    stack: this.stack,
    stackLabel: this.stackLabel,
    complexity: this.complexity,
    designPreferences: this.designPreferences,
    status: this.status,
    fileCount: this.files?.length || 0,
    entryFile: this.entryFile || '',
    techStack: this.techStack,
    dependencies: this.dependencies,
    previewSupported: Boolean(this.previewSupported),
    creditsUsed: this.creditsUsed,
    generatedAt: this.generatedAt,
    errorCode: this.errorCode || '',
    createdAt: this.createdAt,
    updatedAt: this.updatedAt,
    errorMessage: this.errorMessage || '',
  };
};

/** Full project, including file contents and README. */
aiProjectSchema.methods.toOwnerJSON = function toOwnerJSON() {
  return {
    ...this.toSummaryJSON(),
    files: (this.files || []).map((file) => ({
      path: file.path,
      language: file.language,
      content: file.content,
      updatedAt: file.updatedAt,
    })),
    readme: this.readme || '',
    setupSteps: this.setupSteps || [],
    apiEndpoints: this.apiEndpoints || [],
    previewHtml: this.previewHtml || '',
    provider: this.provider || '',
    model: this.model || '',
  };
};

/** Admin shape: no file contents, just usage facts. */
aiProjectSchema.methods.toAdminJSON = function toAdminJSON(userEmail = '') {
  return {
    id: this._id.toString(),
    userId: this.userId.toString(),
    userEmail,
    title: this.title,
    stack: this.stack,
    complexity: this.complexity,
    status: this.status,
    fileCount: this.files?.length || 0,
    entryFile: this.entryFile || '',
    creditsUsed: this.creditsUsed,
    provider: this.provider || '',
    model: this.model || '',
    createdAt: this.createdAt,
    generatedAt: this.generatedAt,
    errorCode: this.errorCode || '',
  };
};

export const AiProject = mongoose.model('AiProject', aiProjectSchema);
